CREATE TABLE `OUTILS_1_GRILLE` (
  `Corps` varchar(100) DEFAULT NULL,
  `Grade` varchar(100) DEFAULT NULL,
  `Categorie` varchar(2) DEFAULT NULL,
  `Filiere` varchar(75) DEFAULT NULL,
  `CAT` varchar(3) DEFAULT NULL,
  `echelon` varchar(10) DEFAULT NULL,
  `indice_brut` int DEFAULT NULL,
  `indice_maj` int DEFAULT NULL,
  `duree` varchar(50) DEFAULT NULL,
  `code` varchar(30) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;



ALTER TABLE `OUTILS_1_GRILLE`
  ADD PRIMARY KEY (`code`);
COMMIT;
